import os
from flask import Flask, request, jsonify

app = Flask(__name__)

DATA_DIR = "/data"


def _resolve_search_dir(search_dir):
    """Resolve search_dir relative to DATA_DIR, preventing path traversal."""
    if not search_dir:
        return DATA_DIR

    # Normalize the requested directory
    if os.path.isabs(search_dir):
        candidate = os.path.normpath(search_dir)
    else:
        candidate = os.path.normpath(os.path.join(DATA_DIR, search_dir))

    base = os.path.normpath(DATA_DIR)

    # Ensure the resolved path stays within DATA_DIR
    if candidate != base and not candidate.startswith(base + os.sep):
        return None

    return candidate


def _file_matches_content(path, search_content):
    """Check if a file contains the given content (text search)."""
    try:
        with open(path, "r", encoding="utf-8", errors="ignore") as f:
            return search_content in f.read()
    except (OSError, IOError):
        return False


@app.route("/search", methods=["POST"])
def search():
    if not request.is_json:
        return jsonify({"error": "Request body must be JSON"}), 400

    try:
        payload = request.get_json(silent=False)
    except Exception:
        return jsonify({"error": "Invalid JSON"}), 400

    if payload is None:
        payload = {}

    if not isinstance(payload, dict):
        return jsonify({"error": "Request body must be a JSON object"}), 400

    search_content = payload.get("search_content")
    search_filename = payload.get("search_filename")
    search_dir = payload.get("search_dir")

    # Validate types
    for field_name, value in (
        ("search_content", search_content),
        ("search_filename", search_filename),
        ("search_dir", search_dir),
    ):
        if value is not None and not isinstance(value, str):
            return jsonify({"error": f"{field_name} must be a string or null"}), 400

    # At least one search criterion should be provided
    if not search_content and not search_filename:
        return jsonify({"error": "Provide search_content and/or search_filename"}), 400

    resolved_dir = _resolve_search_dir(search_dir)
    if resolved_dir is None:
        return jsonify({"error": "Invalid search_dir"}), 400

    if not os.path.isdir(resolved_dir):
        return jsonify({"files": []}), 200

    results = []

    for root, _dirs, files in os.walk(resolved_dir):
        for name in files:
            full_path = os.path.join(root, name)

            # Ensure symlinks / traversal don't escape DATA_DIR
            real_path = os.path.realpath(full_path)
            real_base = os.path.realpath(DATA_DIR)
            if real_path != real_base and not real_path.startswith(real_base + os.sep):
                continue

            matched = False

            if search_filename:
                # Match filename: exact match or startswith
                if name == search_filename or name.startswith(search_filename):
                    matched = True

            if not matched and search_content:
                if _file_matches_content(full_path, search_content):
                    matched = True

            if matched:
                results.append(full_path)

    results.sort()
    return jsonify({"files": results}), 200


if __name__ == "__main__":
    app.run(host="0.0.0.0", port=5000)

